package io.tenvyr.platform.domain;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.Json;
import java.nio.charset.StandardCharsets;
import java.util.*;
public final class ExecutionState {
    public static final int MAX_STATE_KEYS=128,MAX_KEY_LENGTH=128,MAX_PATCH_OPERATIONS=128,MAX_PATCH_BYTES=16384,MAX_STATE_BYTES=65536;
    private static final Set<String> DANGEROUS=Set.of("__proto__","prototype","constructor");
    private ExecutionState(){}
    public static void validateStateKey(String key){if(DANGEROUS.contains(key))throw invalid("key \""+key+"\" is not allowed");if(key.codePointCount(0,key.length())>128)throw invalid("key exceeds 128 Unicode code points");}
    public static ObjectNode validateStatePatch(JsonNode input){if(input==null||!input.isObject())throw invalid("patch must be a plain object");for(String key:Json.keys(input))if(!Set.of("set","delete").contains(key))throw invalid("unknown patch field \""+key+"\"");ObjectNode set=Json.object();ArrayNode deleted=Json.array();int operations=0;
        if(input.has("set")){JsonNode raw=input.get("set");if(!raw.isObject())throw invalid("patch \"set\" must be a plain object");operations+=raw.size();for(String key:Json.keys(raw)){validateStateKey(key);jsonValueUtf8Size(raw.get(key));}set=(ObjectNode)raw.deepCopy();}
        if(input.has("delete")){JsonNode raw=input.get("delete");if(!raw.isArray())throw invalid("patch \"delete\" must be an array of strings");operations+=raw.size();Set<String> unique=new HashSet<>();for(JsonNode key:raw){if(!key.isTextual())throw invalid("patch \"delete\" entries must be strings");validateStateKey(key.asText());if(!unique.add(key.asText()))throw invalid("patch \"delete\" contains duplicate keys");deleted.add(key);}}
        if(operations>128)throw invalid("patch exceeds 128 operations");for(JsonNode key:deleted)if(set.has(key.asText()))throw invalid("key \""+key.asText()+"\" cannot appear in both set and delete");ObjectNode sized=Json.object();if(!set.isEmpty())sized.set("set",set);if(!deleted.isEmpty())sized.set("delete",deleted);if(jsonValueUtf8Size(sized)>16384)throw invalid("patch exceeds 16384 bytes");return Json.object("set",set,"delete",deleted);
    }
    public static ObjectNode applyStatePatch(JsonNode state,JsonNode patch){ObjectNode source=Json.requireObject(state,"state"),result=source.deepCopy();boolean changed=false;for(JsonNode key:patch.path("delete")){if(result.has(key.asText())){result.remove(key.asText());changed=true;}}for(String key:Json.keys(patch.path("set"))){JsonNode next=patch.path("set").get(key);if(source.has(key)&&equal(source.get(key),next))continue;changed=true;result.set(key,next);}if(!changed)return Json.object("state",source,"changed",false);ObjectNode ordered=Json.object();List<String> keys=Json.keys(result);keys.sort(String::compareTo);for(String key:keys)ordered.set(key,result.get(key));return Json.object("state",ordered,"changed",true);}
    private static boolean equal(JsonNode a,JsonNode b){try{return Json.canonical(a).equals(Json.canonical(b));}catch(StackOverflowError e){return false;}}
    /** Iterative size/JSON safety walk preserves deep-input behavior without recursive stack overflow. */
    public static int jsonValueUtf8Size(JsonNode value){record Item(JsonNode value,boolean exit){}Deque<Item> stack=new ArrayDeque<>();Set<JsonNode> active=Collections.newSetFromMap(new IdentityHashMap<>());stack.push(new Item(value,false));long size=0;while(!stack.isEmpty()){Item item=stack.pop();JsonNode n=item.value();if(item.exit()){active.remove(n);continue;}if(n==null||n.isNull()){size+=4;continue;}if(n.isContainerNode()){if(!active.add(n))throw invalid("value contains a cycle");stack.push(new Item(n,true));size+=2+Math.max(0,n.size()-1);if(n.isObject()){for(String key:Json.keys(n)){if(DANGEROUS.contains(key))throw invalid("value contains an unsafe object key");size+=Json.quote(key).getBytes(StandardCharsets.UTF_8).length+1;stack.push(new Item(n.get(key),false));}}else for(JsonNode child:n)stack.push(new Item(child,false));}else if(n.isTextual())size+=Json.quote(n.asText()).getBytes(StandardCharsets.UTF_8).length;else if(n.isNumber()){if(!Double.isFinite(n.doubleValue()))throw invalid("value contains NaN or Infinity");size+=Json.jsNumber(n.doubleValue()).length();}else if(n.isBoolean())size+=n.asBoolean()?4:5;else throw invalid("value contains a non-JSON value");if(size>Integer.MAX_VALUE)throw invalid("value exceeds supported byte size");}return (int)size;}
    public static void validateState(JsonNode state){if(state==null||!state.isObject())throw invalid("state must be a plain object");if(state.size()>MAX_STATE_KEYS)throw invalid("state exceeds 128 keys");for(String key:Json.keys(state))validateStateKey(key);if(jsonValueUtf8Size(state)>MAX_STATE_BYTES)throw invalid("state exceeds 65536 bytes");}
    private static DomainError invalid(String message){return new DomainError("EXECUTION_STATE_INVALID",message);}
}
